#!/bin/sh
# Regenerates the algae cluster charts. Run from the repo root.
K=~/.claude/skills/fishcare-page/scripts; D=assets/guides/algae; mkdir -p $D
C(){ python3 $K/images.py chart "$@" 2>&1 | grep wrote; }
C --out $D/algae-eater-fish-by-tank-size.svg --title "Algae eater fish by tank size: what eats algae in a 5 to 75 gallon tank" --subtitle "Freshwater algae eaters matched to tank size and the algae they actually eat. One adult per row unless stated." --row "5–10 gallons|nerite snail, amano shrimp|green film, spot algae, diatoms" --row "10–20 gallons|otocinclus (group of 6)|diatoms, soft green film" --row "20–29 gallons|bristlenose pleco, cherry shrimp|green film, biofilm, wood" --row "29–40 gallons|siamese algae eater (3+)|black beard algae, hair algae" --row "40–55 gallons|rubber-lip pleco, clown pleco|green film, spot algae" --row "55–75 gallons|American-flag fish, mollies|hair and thread algae" --row "Never for algae|common pleco, chinese algae eater|outgrow tanks, stop eating algae" --alt "Algae eater fish chart by tank size: nerite snail and amano shrimp for 5 to 10 gallons, otocinclus for 10 to 20 gallons, bristlenose pleco for 20 to 29 gallons, siamese algae eater for 29 to 40 gallons, rubber-lip pleco for 40 to 55 gallons, flag fish and mollies for 55 to 75 gallons; common pleco and chinese algae eater not recommended" --footer "No algae eater fixes the cause. Pair the animal with the fix on the algae control page."
C --out $D/siamese-algae-eaters-vs-lookalikes.svg --title "Siamese algae eaters vs the look-alikes sold under the same name" --subtitle "True SAE (Crossocheilus oblongus) against flying fox, false SAE and the Chinese algae eater." --row "True siamese algae eater|black stripe runs into the tail fork|clear fins, eats black beard algae, 6 in, peaceful" --row "Flying fox (Epalzeorhynchos)|stripe stops at tail base|gold line above stripe, red-edged fins, less algae" --row "False SAE (Garra cambodgiensis)|stripe stops at tail base|two barbel pairs, black-edged fins, eats little algae" --row "Chinese algae eater (Gyrinocheilus)|sucker mouth, 11 in adult|stops eating algae at 4 in, rasps slime off slow fish" --row "Tank size|30 gal for 3+ SAE|55 gal for a Chinese algae eater" --row "Temperature|75–79°F (24–26°C)|72–82°F for the Chinese algae eater" --alt "Siamese algae eaters comparison chart: true SAE has a black stripe running into the tail fork and eats black beard algae; flying fox and false SAE stripes stop at the tail base; chinese algae eater has a sucker mouth, grows to 11 inches and stops eating algae at 4 inches" --footer "Shops label all four as siamese algae eaters. Check the stripe and the fins before you buy."
C --out $D/how-to-get-rid-of-algae-in-fish-tank-plan.svg --title "How to get rid of algae in a fish tank: the 7-step plan" --subtitle "Aquarium algae control in order. Each step removes a cause; algae eaters and drops come last, not first." --row "1. Cut the light|6–8 hours a day on a timer|no window sun; most common cause" --row "2. Test the water|nitrate <20 ppm, phosphate <0.5 ppm|feed less; algae eats the excess" --row "3. Water changes|25–30% weekly for 4 weeks|export nutrients, reset CO2 balance" --row "4. Scrub and siphon|glass, rock, wood, gravel|remove the bulk by hand" --row "5. Fix the filter|clean media, boost flow|dead spots grow algae" --row "6. Add plants or eaters|fast plants, then SAE, oto, nerite|outcompete, then graze" --row "7. Algae control drops|last resort, half dose|never with shrimp or plants" --alt "How to get rid of algae in fish tank chart: cut light to 6 to 8 hours, test nitrate under 20 ppm and phosphate under 0.5 ppm, 25 to 30 percent weekly water changes, scrub and siphon, fix filter flow, add plants and algae eaters, algae control drops only as a last resort" --footer "Expect 3 to 4 weeks. Algae that comes back means a step was skipped."
C --out $D/black-beard-algae-types-chart.svg --title "Black beard algae and the other algae in a fish tank: how to tell them apart" --subtitle "Colour, texture and where it grows identify the algae; the cause tells you the fix." --row "Black beard algae (BBA)|black to dark red tufts, 0.2–0.5 in|leaf edges, wood, filter outlet · unstable CO2, low flow" --row "Staghorn / black brush algae|grey-black branching strands|leaf tips · ammonia spikes, dirty filter" --row "Brown algae (diatoms)|dusty brown film, wipes off|new tanks under 3 months · silicates, low light" --row "Blue-green algae|slimy blue-green sheets, smells|substrate, glass line · cyanobacteria, low nitrate" --row "Hair algae|green threads, 1–3 in|plants, wood · excess light and nutrients" --row "Green spot algae|hard green dots|glass, anubias · low phosphate, high light" --row "Macro algae|leafy marine algae|saltwater only · grown on purpose in refugiums" --alt "Black beard algae identification chart: BBA is black to dark red tufts on leaf edges and wood from unstable CO2; staghorn or black brush algae is grey branching strands; brown algae is a dusty diatom film in new tanks; blue-green algae is slimy sheets of cyanobacteria; hair algae is green threads; green spot algae is hard dots; macro algae is leafy marine algae grown on purpose" --footer "BBA and staghorn are red algae (Rhodophyta) despite the colour, which is why they bleach red under hydrogen peroxide."
C --out $D/filtration-canister-flow-by-tank-size.svg --title "Filtration canister flow rate by tank size" --subtitle "Rated pump flow of a tank canister filter, using the 4x to 6x tank volume per hour rule. Real flow is 30 to 50% lower with media." --row "20–29 gallons|120–180 GPH|smallest canister worth buying" --row "40–55 gallons|220–330 GPH|the sweet spot for one canister" --row "75 gallons|300–450 GPH|one large or two mid-size canisters" --row "90–125 gallons|450–750 GPH|two canisters or a sump" --row "150–180 gallons|750–1,000+ GPH|sump usually cheaper" --row "Public aquariums|sand filters, protein skimmers, ozone|thousands of gallons per minute" --alt "Filtration canister flow rate chart: 120 to 180 GPH for 20 to 29 gallons, 220 to 330 GPH for 40 to 55 gallons, 300 to 450 GPH for 75 gallons, 450 to 750 GPH for 90 to 125 gallons, over 750 GPH for 150 gallons and up; public aquariums use sand filters and protein skimmers" --footer "Heavily stocked tanks (goldfish, cichlids, plecos) take the top of each range or the next size up."
